CONSISTENCY QUORUM;
INSERT INTO users_by_email (email, user_id) VALUES ('ana@example.com', 42);
SELECT user_id FROM users_by_email WHERE email = 'ana@example.com';

CONSISTENCY ONE; -- mais rápido, possivelmente desatualizado

BEGIN;
INSERT INTO orders (id, customer_id, total) VALUES (1001, 42, 59.80);
INSERT INTO outbox (aggregate_id, type, payload)
VALUES (1001, 'order_created', '{"total": 59.80}');
COMMIT;
